"""Basis pengetahuan Local Mode: perintah terminal tambahan."""
from __future__ import annotations

from linuxai.local.entry import Entry, T


def C(name: str, keys: str, fungsi: str, contoh: str, catatan: str = "") -> Entry:
    text = f"`{name}` {fungsi}\n\nContoh:\n```\n{contoh}\n```"
    if catatan:
        text += f"\n{catatan}"
    return T(f"cmd-{name}", f"Perintah {name}", keys, text, cmd=True)


